2	import java.math.RoundingMode;
3	import java.util.List;
4	
5	/**
6	 * The MHPCO premium rules: policy-wide modifiers, the processing fee, and
7	 * rounding in the office's favor, applied to the base premium the
8	 * {@link PriceList} states for the insured items.
9	 *
10	 * Intermediate amounts stay exact fractions; only the final premium is rounded.
11	 */
12	public class PremiumPolicy {
13	
14	    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = new BigDecimal("0.10");
15	    private static final BigDecimal PROCESSING_FEE = new BigDecimal("5");
16	
17	    private final PriceList priceList = new PriceList();
18	
19	    public int quote(List<String> itemTypes) {
20	        BigDecimal policyBasePremium = priceList.policyBasePremium(itemTypes);
21	        BigDecimal withPolicyModifiers = policyBasePremium
22	                .add(policyBasePremium.multiply(FIRST_INSURANCE_SURCHARGE_RATE));
23	        return inOfficesFavor(withPolicyModifiers.add(PROCESSING_FEE));
24	    }
25	
26	    private int inOfficesFavor(BigDecimal premium) {
27	        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
28	    }
29	}
