1	import java.math.BigDecimal;
2	import java.util.LinkedHashMap;
3	import java.util.List;
4	import java.util.Map;
5	import java.util.Set;
6	
7	/**
8	 * The MHPCO price list: what the office charges as base premium for the items a
9	 * policy covers. Main items are priced individually; every component costs the
10	 * same per-component rate whichever type it is, and a building block of alike
11	 * components is offered at a special rate.
12	 *
13	 * The per-component rate ignores the component's type, but the block rate does
14	 * not: a block is a quantity of <em>alike</em> components, so the tariff also
15	 * decides which items count as alike (see {@link #alikenessGroupOf}) and groups
16	 * them before pricing.
17	 *
18	 * This is the office's tariff. It changes on its own schedule, independently of
19	 * the modifier rules in {@link PremiumPolicy}.
20	 */
21	public class PriceList {
22	
23	    private static final Map<String, BigDecimal> MAIN_ITEM_BASE_PREMIUM = Map.of(
24	            "sword", new BigDecimal("100"),
25	            "amulet", new BigDecimal("60"),
26	            "staff", new BigDecimal("80"),
27	            "potion", new BigDecimal("40"));
28	
29	    /** Components are all priced at one rate per component, whatever their type. */
30	    private static final BigDecimal COMPONENT_BASE_PREMIUM = new BigDecimal("25");
31	
32	    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");
33	
34	    /** A building block of exactly 3 alike components is offered at this rate. */
35	    private static final BigDecimal COMPONENT_BLOCK_BASE_PREMIUM = new BigDecimal("60");
36	    private static final int COMPONENT_BLOCK_SIZE = 3;
37	
38	    /** The base premium for all items a policy covers, alike items priced together. */
39	    public BigDecimal policyBasePremium(List<String> itemTypes) {
40	        BigDecimal total = BigDecimal.ZERO;
41	        for (Map.Entry<String, Integer> alikeItems : groupedByAlikeness(itemTypes).entrySet()) {
42	            total = total.add(basePremium(alikeItems.getKey(), alikeItems.getValue()));
43	        }
44	        return total;
45	    }
46	
47	    private static Map<String, Integer> groupedByAlikeness(List<String> itemTypes) {
48	        Map<String, Integer> counts = new LinkedHashMap<>();
49	        for (String itemType : itemTypes) {
50	            counts.merge(alikenessGroupOf(itemType), 1, Integer::sum);
51	        }
52	        return counts;
53	    }
54	
55	    /**
56	     * The office counts two items as alike when they are of exactly the same
57	     * type, not merely of the same family: 2 runes and a moonstone are three
58	     * loose components priced at 75 G, never a block, because a moonstone is not
59	     * a rune. Widening "alike" to a family (rune-y, gemstone-y) would mean
60	     * returning a family name here instead of the type itself.
61	     */
62	    private static String alikenessGroupOf(String itemType) {
63	        return itemType;
64	    }
65	
66	    private static BigDecimal basePremium(String itemType, int count) {
67	        if (COMPONENT_TYPES.contains(itemType)) {
68	            return componentsBasePremium(count);
69	        }
70	        return MAIN_ITEM_BASE_PREMIUM.get(itemType).multiply(BigDecimal.valueOf(count));
71	    }
72	
73	    private static BigDecimal componentsBasePremium(int count) {
74	        if (qualifiesForBlockRate(count)) {
75	            return COMPONENT_BLOCK_BASE_PREMIUM;
76	        }
77	        return COMPONENT_BASE_PREMIUM.multiply(BigDecimal.valueOf(count));
78	    }
79	
80	    /**
81	     * The office grants the block rate only to a holding of exactly 3 alike
82	     * components. It neither prices a part of a block at the block rate (4
83	     * components are not a block) nor breaks a larger holding down into blocks
84	     * (7 components are priced as 7, not as two blocks and one loose component).
85	     */
86	    private static boolean qualifiesForBlockRate(int alikeComponentCount) {
87	        return alikeComponentCount == COMPONENT_BLOCK_SIZE;
88	    }
89	}
